-- =============================================================================
-- SAIL Tour Management System — TA_RULE_MASTER seed data
-- Source: SAIL Travelling Allowance (TA) Rules-2021, Ref. PER/RULES/4001,
-- effective 17-Dec-2021 (PDF S6.0 grade-wise entitlement, S7.2A lodging/DA).
--
-- Modeled at individual-grade granularity (not the source table's row groupings)
-- because the PDF uses three DIFFERENT groupings for (a) rail/air/road-mileage
-- entitlement, (b) DA rates, and (c) lodging ceilings. One row per exact grade
-- avoids misapplying a rate across a boundary the source document itself draws
-- differently in each table, and lets the rule engine do a single exact-match
-- lookup by employee grade rather than re-deriving group membership in code.
--
-- S-1/S-2 are further split by service length (<5 years vs >=5 years) because
-- that is the one place the PDF's own entitlement table conditions the rate on
-- a non-grade attribute.
--
-- NULL road_mileage_rate / lodging ceiling means "Actual", per the source rule
-- (Chairman/Director road mileage; E-9 and Chairman/Director lodging).
--
-- discretionary_mode_flag = 'Y' for E-7 and above only (SSoT S15.3: "E-7 and
-- above executives may perform tour journeys by any mode at their discretion").
-- E-6 and below always require Competent Authority approval for a higher/
-- different mode/class — this is enforced in the TA rule engine, not this table.
-- =============================================================================

INSERT INTO ta_rule_master (rule_id, grade_code, grade_label, rail_entitlement, waterway_entitlement, air_entitlement, air_min_distance_km, air_region_exception_flag, road_mileage_rate, da_hotel_rate, da_own_arrangement_rate, lodging_ceiling_specified, lodging_ceiling_other, discretionary_mode_flag, effective_from) VALUES (ta_rule_master_seq.NEXTVAL, 'S1_LT5YR', 'S-1 (less than 5 years of service)', '3AC', 'Middle class', 'NOT_ENTITLED', NULL, 'N', 4.0, 450, 650, 1200, 1000, 'N', DATE '2021-12-17');
